1	import { useState, useMemo } from "react";
2	import {
3	  useListPlayers, useCreatePlayer, useUpdatePlayer, useDeletePlayer,
4	  useAiEnhancePlayer, getListPlayersQueryKey,
5	} from "@workspace/api-client-react";
6	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
7	import { Button } from "@/components/ui/button";
8	import { Input } from "@/components/ui/input";
9	import { Textarea } from "@/components/ui/textarea";
10	import { Skeleton } from "@/components/ui/skeleton";
11	import { Label } from "@/components/ui/label";
12	import { Badge } from "@/components/ui/badge";
13	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
14	import { Plus, Edit2, Trash2, Users, Sparkles, Loader2, X, ChevronDown, ChevronRight } from "lucide-react";
15	import { useQueryClient } from "@tanstack/react-query";
16	import { type Player } from "@workspace/api-client-react";
17	import { useToast } from "@/hooks/use-toast";
18	
19	// ─── Player type system ───────────────────────────────────────────────────────
20	
21	const PLAYER_TYPES = ["Character", "NPC", "Enemy", "Boss", "Creature", "Ally"] as const;
22	type PlayerType = typeof PLAYER_TYPES[number];
23	
24	const PLAYER_TYPE_META: Record<PlayerType, { icon: string; label: string; color: string; badge: string; desc: string }> = {
25	  Character: { icon: "👤", label: "Player Characters", color: "text-blue-400",   badge: "bg-blue-500/20 text-blue-400 border-blue-500/30",   desc: "Playable heroes, protagonists, roles" },
26	  NPC:       { icon: "🧑", label: "NPCs",              color: "text-green-400",  badge: "bg-green-500/20 text-green-400 border-green-500/30",  desc: "Allies, merchants, quest givers" },
27	  Enemy:     { icon: "👹", label: "Enemies",            color: "text-red-400",    badge: "bg-red-500/20 text-red-400 border-red-500/30",        desc: "Opponents, monsters, minions" },
28	  Boss:      { icon: "💀", label: "Bosses",             color: "text-orange-400", badge: "bg-orange-500/20 text-orange-400 border-orange-500/30", desc: "Elite enemies, final bosses" },
29	  Creature:  { icon: "🐉", label: "Creatures",          color: "text-purple-400", badge: "bg-purple-500/20 text-purple-400 border-purple-500/30", desc: "Animals, beasts, summons" },
30	  Ally:      { icon: "🤝", label: "Allies",             color: "text-cyan-400",   badge: "bg-cyan-500/20 text-cyan-400 border-cyan-500/30",    desc: "Companions, helpers, followers" },
31	};
32	
33	function getTypeMeta(type: string) {
34	  return PLAYER_TYPE_META[type as PlayerType] ?? PLAYER_TYPE_META.Character;
35	}
36	
37	// ─── Main component ───────────────────────────────────────────────────────────
38	
39	interface PlayersProps {
40	  projectId: number;
41	}
42	
43	export function Players({ projectId }: PlayersProps) {
44	  const queryClient = useQueryClient();
45	  const { data: players, isLoading } = useListPlayers(projectId);
46	  const createPlayer = useCreatePlayer();
47	  const updatePlayer = useUpdatePlayer();
48	  const deletePlayer = useDeletePlayer();
49	  const enhancePlayer = useAiEnhancePlayer();
50	  const { toast } = useToast();
51	
52	  const [enhancingId, setEnhancingId] = useState<number | null>(null);
53	  const [showAdd, setShowAdd] = useState(false);
54	  const [editPlayerId, setEditPlayerId] = useState<number | null>(null);
55	  const [collapsedGroups, setCollapsedGroups] = useState<Set<PlayerType>>(new Set());
56	  const [filterType, setFilterType] = useState<PlayerType | "all">("all");
57	
58	  const [formData, setFormData] = useState({
59	    name: "", playerType: "Character" as PlayerType, role: "", description: "", strategy: "",
60	  });
61	
62	  const isFormOpen = showAdd || editPlayerId !== null;
63	  const isEditing = editPlayerId !== null;
64	
65	  const closeForm = () => {
66	    setShowAdd(false);
67	    setEditPlayerId(null);
68	    setFormData({ name: "", playerType: "Character", role: "", description: "", strategy: "" });
69	  };
70	
71	  const handleCreate = async () => {
72	    if (!formData.name) return;
73	    try {
74	      await createPlayer.mutateAsync({ projectId, data: formData });
75	      closeForm();
76	      queryClient.invalidateQueries({ queryKey: getListPlayersQueryKey(projectId) });
77	    } catch (err) {
78	      toast({ title: "Could not create", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
79	    }
80	  };
81	
82	  const handleUpdate = async () => {
83	    if (!editPlayerId || !formData.name) return;
84	    try {
85	      await updatePlayer.mutateAsync({ projectId, playerId: editPlayerId, data: formData });
86	      closeForm();
87	      queryClient.invalidateQueries({ queryKey: getListPlayersQueryKey(projectId) });
88	    } catch (err) {
89	      toast({ title: "Could not update", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
90	    }
91	  };
92	
93	  const handleDelete = async (id: number) => {
94	    await deletePlayer.mutateAsync({ projectId, playerId: id });
95	    queryClient.invalidateQueries({ queryKey: getListPlayersQueryKey(projectId) });
96	  };
97	
98	  const handleEnhance = async (playerId: number) => {
99	    setEnhancingId(playerId);
100	    try {
101	      await enhancePlayer.mutateAsync({ projectId, playerId });
102	      queryClient.invalidateQueries({ queryKey: getListPlayersQueryKey(projectId) });
103	      toast({ title: "Profile enhanced" });
104	    } catch (err) {
105	      toast({ title: "Enhance failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
106	    } finally {
107	      setEnhancingId(null);
108	    }
109	  };
110	
111	  const openAdd = (defaultType?: PlayerType) => {
112	    setEditPlayerId(null);
113	    setFormData({ name: "", playerType: defaultType ?? "Character", role: "", description: "", strategy: "" });
114	    setShowAdd(true);
115	  };
116	
117	  const openEdit = (player: Player) => {
118	    setShowAdd(false);
119	    setFormData({
120	      name: player.name,
121	      playerType: (player.playerType as PlayerType) ?? "Character",
122	      role: player.role || "",
123	      description: player.description || "",
124	      strategy: player.strategy || "",
125	    });
126	    setEditPlayerId(player.id);
127	  };
128	
129	  const toggleGroup = (type: PlayerType) =>
130	    setCollapsedGroups((prev) => { const s = new Set(prev); s.has(type) ? s.delete(type) : s.add(type); return s; });
131	
132	  // Group players by type
133	  const grouped = useMemo(() => {
134	    const map = new Map<PlayerType, Player[]>();
135	    PLAYER_TYPES.forEach((t) => map.set(t, []));
136	    (players ?? []).forEach((p) => {
137	      const t = (p.playerType as PlayerType) ?? "Character";
138	      if (!map.has(t)) map.set(t, []);
139	      map.get(t)!.push(p);
140	    });
141	    return map;
142	  }, [players]);
143	
144	  const typeCounts = useMemo(() => {
145	    const out: Partial<Record<PlayerType, number>> = {};
146	    (players ?? []).forEach((p) => {
147	      const t = (p.playerType as PlayerType) ?? "Character";
148	      out[t] = (out[t] ?? 0) + 1;
149	    });
150	    return out;
151	  }, [players]);
152	
153	  const filteredPlayers = useMemo(() => {
154	    if (filterType === "all") return players ?? [];
155	    return (players ?? []).filter((p) => (p.playerType ?? "Character") === filterType);
156	  }, [players, filterType]);
157	
158	  return (
159	    <div className="space-y-6 pb-8">
160	      {/* Header */}
161	      <div className="flex justify-between items-center flex-wrap gap-3">
162	        <div>
163	          <h2 className="text-xl font-bold flex items-center gap-2">
164	            <Users className="h-5 w-5 text-primary" /> Characters &amp; Personas
165	          </h2>
166	          <p className="text-xs text-muted-foreground mt-0.5">
167	            {players?.length ?? 0} profiles — player characters, NPCs, enemies, bosses, creatures, and allies
168	          </p>
169	        </div>
170	        {!isFormOpen && (
171	          <Button onClick={() => openAdd()} data-testid="add-player-button">
172	            <Plus className="h-4 w-4 mr-2" /> Add Profile
173	          </Button>
174	        )}
175	      </div>
176	
177	      {/* Add / Edit form */}
178	      {isFormOpen && (
179	        <Card className="bg-card border-primary/40" data-testid="player-form-panel">
180	          <CardHeader className="pb-3 flex flex-row items-center justify-between space-y-0">
181	            <CardTitle className="text-base">{isEditing ? "Edit Profile" : "New Profile"}</CardTitle>
182	            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={closeForm}><X className="h-4 w-4" /></Button>
183	          </CardHeader>
184	          <CardContent className="space-y-4">
185	            {/* Name + Type */}
186	            <div className="flex gap-3">
187	              <div className="flex-1 space-y-2">
188	                <Label>Name / Persona *</Label>
189	                <Input value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })}
190	                  placeholder="e.g. The Warrior, Village Elder, Goblin Scout…" autoFocus />
191	              </div>
192	              <div className="w-44 space-y-2 shrink-0">
193	                <Label>Type</Label>
194	                <Select value={formData.playerType} onValueChange={(v) => setFormData({ ...formData, playerType: v as PlayerType })}>
195	                  <SelectTrigger><SelectValue /></SelectTrigger>
196	                  <SelectContent>
197	                    {PLAYER_TYPES.map((t) => {
198	                      const m = getTypeMeta(t);
199	                      return <SelectItem key={t} value={t}>{m.icon} {t}</SelectItem>;
200	                    })}
201	                  </SelectContent>
202	                </Select>
203	              </div>
204	            </div>
205	
206	            <div className="space-y-2">
207	              <Label>Role</Label>
208	              <Input value={formData.role} onChange={(e) => setFormData({ ...formData, role: e.target.value })}
209	                placeholder={
210	                  formData.playerType === "Character" ? "e.g. Tank, Support, Damage" :
211	                  formData.playerType === "NPC"       ? "e.g. Merchant, Quest Giver, Guide" :
212	                  formData.playerType === "Enemy"     ? "e.g. Minion, Elite, Ranged" :
213	                  formData.playerType === "Boss"      ? "e.g. Final Boss, Mini-boss, Arena Champion" :
214	                  formData.playerType === "Creature"  ? "e.g. Mount, Summon, Wild Animal" :
215	                  "e.g. Healer, Scout, Tank"
216	                }
217	              />
218	            </div>
219	            <div className="space-y-2">
220	              <Label>Description</Label>
221	              <Textarea value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })}
222	                placeholder="Who are they and what makes them unique?" />
223	            </div>
224	            <div className="space-y-2">
225	              <Label>
226	                {formData.playerType === "Character" ? "Typical Strategy" :
227	                 formData.playerType === "Enemy" || formData.playerType === "Boss" ? "Tactics / Behavior" :
228	                 "Notes / Behavior"}
229	              </Label>
230	              <Textarea value={formData.strategy} onChange={(e) => setFormData({ ...formData, strategy: e.target.value })}
231	                placeholder={
232	                  formData.playerType === "Character" ? "How does a player optimally play this character?" :
233	                  formData.playerType === "Enemy" || formData.playerType === "Boss" ? "How does this enemy act in combat or encounters?" :
234	                  "Any notable behavior or design notes."
235	                }
236	              />
237	            </div>
238	            <div className="flex justify-end gap-2 pt-2">
239	              <Button variant="outline" onClick={closeForm}>Cancel</Button>
240	              <Button onClick={isEditing ? handleUpdate : handleCreate} disabled={!formData.name || createPlayer.isPending || updatePlayer.isPending}>
241	                {(createPlayer.isPending || updatePlayer.isPending) && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
242	                {isEditing ? "Save Changes" : "Create"}
243	              </Button>
244	            </div>
245	          </CardContent>
246	        </Card>
247	      )}
248	
249	      {/* Filter pills */}
250	      {players && players.length > 0 && (
251	        <div className="flex gap-1.5 flex-wrap">
252	          <button onClick={() => setFilterType("all")}
253	            className={`text-xs px-2.5 py-1 rounded-full border transition-colors ${filterType === "all" ? "bg-white/10 text-white border-white/20" : "text-muted-foreground border-border hover:text-white"}`}
254	          >
255	            All ({players.length})
256	          </button>
257	          {PLAYER_TYPES.map((t) => {
258	            const count = typeCounts[t];
259	            if (!count) return null;
260	            const m = getTypeMeta(t);
261	            return (
262	              <button key={t} onClick={() => setFilterType(filterType === t ? "all" : t)}
263	                className={`text-xs px-2.5 py-1 rounded-full border transition-colors flex items-center gap-1 ${filterType === t ? m.badge : "text-muted-foreground border-border hover:text-white"}`}
264	              >
265	                <span>{m.icon}</span> {t} ({count})
266	              </button>
267	            );
268	          })}
269	        </div>
270	      )}
271	
272	      {/* Player list */}
273	      {isLoading ? (
274	        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
275	          {[1, 2, 3].map((i) => <Skeleton key={i} className="h-48 w-full" />)}
276	        </div>
277	      ) : !players || players.length === 0 ? (
278	        <div className="text-center py-16 border border-dashed border-border rounded-xl bg-card/50">
279	          <Users className="h-10 w-10 text-muted-foreground mx-auto mb-4" />
280	          <h3 className="text-lg font-medium">No profiles yet</h3>
281	          <p className="text-muted-foreground mt-1">Add player characters, NPCs, enemies, bosses, creatures, and allies.</p>
282	          <div className="flex gap-2 justify-center mt-4 flex-wrap">
283	            {PLAYER_TYPES.map((t) => {
284	              const m = getTypeMeta(t);
285	              return (
286	                <Button key={t} variant="outline" size="sm" onClick={() => openAdd(t)}>
287	                  {m.icon} {t}
288	                </Button>
289	              );
290	            })}
291	          </div>
292	        </div>
293	      ) : filterType !== "all" ? (
294	        // Single-type filtered grid
295	        <PlayerGrid
296	          players={filteredPlayers}
297	          onEdit={openEdit}
298	          onDelete={handleDelete}
299	          onEnhance={handleEnhance}
300	          enhancingId={enhancingId}
301	        />
302	      ) : (
303	        // Grouped view by type
304	        <div className="space-y-4">
305	          {PLAYER_TYPES.map((type) => {
306	            const group = grouped.get(type) ?? [];
307	            if (group.length === 0) return null;
308	            const m = getTypeMeta(type);
309	            const isCollapsed = collapsedGroups.has(type);
310	            return (
311	              <div key={type} className="rounded-lg border border-border overflow-hidden">
312	                <button
313	                  onClick={() => toggleGroup(type)}
314	                  className="w-full flex items-center gap-3 px-4 py-2.5 bg-muted/20 hover:bg-muted/30 transition-colors text-left"
315	                >
316	                  {isCollapsed
317	                    ? <ChevronRight className="w-4 h-4 text-muted-foreground shrink-0" />
318	                    : <ChevronDown className="w-4 h-4 text-muted-foreground shrink-0" />}
319	                  <span className="text-base">{m.icon}</span>
320	                  <span className={`text-sm font-semibold ${m.color}`}>{m.label}</span>
321	                  <Badge variant="outline" className={`text-[10px] ml-1 ${m.badge}`}>{group.length}</Badge>
322	                  <span className="text-xs text-muted-foreground ml-1 hidden sm:block">{m.desc}</span>
323	                  <Button
324	                    variant="ghost" size="sm"
325	                    className="ml-auto h-6 px-2 text-xs text-muted-foreground hover:text-white"
326	                    onClick={(e) => { e.stopPropagation(); openAdd(type); }}
327	                  >
328	                    <Plus className="h-3 w-3 mr-1" /> Add
329	                  </Button>
330	                </button>
331	                {!isCollapsed && (
332	                  <div className="p-4">
333	                    <PlayerGrid
334	                      players={group}
335	                      onEdit={openEdit}
336	                      onDelete={handleDelete}
337	                      onEnhance={handleEnhance}
338	                      enhancingId={enhancingId}
339	                    />
340	                  </div>
341	                )}
342	              </div>
343	            );
344	          })}
345	        </div>
346	      )}
347	    </div>
348	  );
349	}
350	
351	// ─── Player card grid ─────────────────────────────────────────────────────────
352	
353	function PlayerGrid({
354	  players, onEdit, onDelete, onEnhance, enhancingId,
355	}: {
356	  players: Player[];
357	  onEdit: (p: Player) => void;
358	  onDelete: (id: number) => void;
359	  onEnhance: (id: number) => void;
360	  enhancingId: number | null;
361	}) {
362	  return (
363	    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
364	      {players.map((player) => {
365	        const m = getTypeMeta((player.playerType as PlayerType) ?? "Character");
366	        return (
367	          <Card key={player.id} className="bg-card border-border overflow-hidden relative group">
368	            <div className="absolute top-3 right-3 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
369	              <Button variant="ghost" size="icon" className="h-7 w-7 bg-background/80 hover:bg-background"
370	                onClick={() => onEnhance(player.id)} disabled={enhancingId === player.id}
371	                title="AI Enhance" data-testid={`enhance-player-${player.id}`}
372	              >
373	                {enhancingId === player.id ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Sparkles className="h-3.5 w-3.5" />}
374	              </Button>
375	              <Button variant="ghost" size="icon" className="h-7 w-7 bg-background/80 hover:bg-background" onClick={() => onEdit(player)}>
376	                <Edit2 className="h-3.5 w-3.5" />
377	              </Button>
378	              <Button variant="ghost" size="icon" className="h-7 w-7 bg-background/80 hover:bg-background hover:text-destructive" onClick={() => onDelete(player.id)}>
379	                <Trash2 className="h-3.5 w-3.5" />
380	              </Button>
381	            </div>
382	
383	            <CardHeader className="pb-2 pt-4 px-4">
384	              <div className="flex items-start gap-2 pr-20">
385	                <span className="text-xl shrink-0 mt-0.5">{m.icon}</span>
386	                <div className="min-w-0">
387	                  <CardTitle className="text-base leading-tight">{player.name}</CardTitle>
388	                  <div className="flex items-center gap-2 mt-1 flex-wrap">
389	                    <Badge variant="outline" className={`text-[10px] ${m.badge}`}>{player.playerType ?? "Character"}</Badge>
390	                    {player.role && (
391	                      <span className="bg-primary/10 text-primary text-xs px-2 py-0.5 rounded border border-primary/20">{player.role}</span>
392	                    )}
393	                  </div>
394	                </div>
395	              </div>
396	            </CardHeader>
397	
398	            <CardContent className="space-y-3 pb-4 px-4">
399	              {player.description && (
400	                <div className="text-sm text-muted-foreground line-clamp-2">{player.description}</div>
401	              )}
402	              {player.strategy && (
403	                <div className="space-y-1">
404	                  <div className={`text-xs font-semibold uppercase tracking-wider ${m.color}`}>
405	                    {(player.playerType === "Enemy" || player.playerType === "Boss") ? "Tactics" : "Strategy"}
406	                  </div>
407	                  <div className="text-sm text-muted-foreground italic border-l-2 border-primary/30 pl-3 py-1 bg-primary/5 rounded-r line-clamp-2">
408	                    {player.strategy}
409	                  </div>
410	                </div>
411	              )}
412	            </CardContent>
413	          </Card>
414	        );
415	      })}
416	    </div>
417	  );
418	}
