227	                {it.tags && (
228	                  <div className="flex flex-wrap gap-1">
229	                    {it.tags.split(",").map(t => t.trim()).filter(Boolean).map(t => (
230	                      <span key={t} className="text-[10px] uppercase font-bold tracking-wider bg-muted text-muted-foreground px-2 py-0.5 rounded border border-border flex items-center gap-1">
231	                        <Tag className="h-2.5 w-2.5" />{t}
232	                      </span>
233	                    ))}
234	                  </div>
235	                )}
236	              </CardContent>
237	            </Card>
238	          ))}
239	        </div>
240	      )}
241	    </div>
242	  );
243	}
