607	            !!s &&
608	            typeof s === "object" &&
609	            typeof s.title === "string" &&
610	            typeof s.content === "string",
611	          ).map((s) => ({
612	            title: s.title,
613	            content: s.content,
614	            category: typeof s.category === "string" ? s.category : "movement",
615	          }))
616	        : [];
617	      const data: AIEnhance = {
618	        rewrittenContent: typeof raw?.rewrittenContent === "string" ? raw.rewrittenContent : "",
619	        improvedTitle: typeof raw?.improvedTitle === "string" ? raw.improvedTitle : rule.title,
620	        designNotes: typeof raw?.designNotes === "string" ? raw.designNotes : undefined,
621	        edgeCases: typeof raw?.edgeCases === "string" ? raw.edgeCases : undefined,
622	        relatedRuleSuggestions: safeRelated,
