27	  definition: string;
28	  autoDetected: boolean;
29	  occurrences: number;
30	}
31	
32	interface RulebookState {
33	  sections: RulebookSection[];
34	  glossary: GlossaryEntry[];
35	  title: string;
36	  version: string;
37	  notes: string;
38	}
39	
40	const STORAGE = (pid: number) => `gameforge.rulebook.${pid}`;
41	
42	const DEFAULT_SECTIONS = (): RulebookSection[] => [
43	  { id: crypto.randomUUID(), type: "setup", title: "Setup", content: "", order: 0, required: true, tips: ["List components", "Starting positions", "Deal hands"] },
44	  { id: crypto.randomUUID(), type: "objective", title: "Objective", content: "", order: 1, required: true, tips: ["Win condition", "Tiebreakers"] },
45	  { id: crypto.randomUUID(), type: "turn-order", title: "Turn Order", content: "", order: 2, required: true, tips: ["Who goes first", "Clockwise or simultaneous"] },
46	  { id: crypto.randomUUID(), type: "actions", title: "Actions", content: "", order: 3, required: true, tips: ["Available actions", "Costs and limits"] },
47	  { id: crypto.randomUUID(), type: "scoring", title: "Scoring", content: "", order: 4, required: true, tips: ["Points earned", "End-game scoring"] },
48	  { id: crypto.randomUUID(), type: "faq", title: "FAQ", content: "", order: 5, required: false, tips: ["Edge cases", "Timing conflicts"] },
49	];
50	
51	const META: Record<string, { color: string }> = {
52	  setup: { color: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30" },
53	  objective: { color: "bg-amber-500/20 text-amber-400 border-amber-500/30" },
54	  "turn-order": { color: "bg-blue-500/20 text-blue-400 border-blue-500/30" },
55	  actions: { color: "bg-violet-500/20 text-violet-400 border-violet-500/30" },
56	  scoring: { color: "bg-rose-500/20 text-rose-400 border-rose-500/30" },
57	  faq: { color: "bg-orange-500/20 text-orange-400 border-orange-500/30" },
58	  custom: { color: "bg-muted text-muted-foreground" },
59	};
60	
61	function load(pid: number): RulebookState {
62	  try { const r = localStorage.getItem(STORAGE(pid)); if (r) return JSON.parse(r); } catch {}
63	  return { sections: DEFAULT_SECTIONS(), glossary: [], title: "Rulebook", version: "1.0", notes: "" };
64	}
65	function save(pid: number, s: RulebookState) { try { localStorage.setItem(STORAGE(pid), JSON.stringify(s)); } catch {} }
66	
67	function detectTerms(text: string): Map<string, number> {
68	  const m = new Map<string, number>();
69	  const raw = text.match(/\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2}\b/g);
70	  if (!raw) return m;
71	  const stopWords = new Set(["The","And","For","But","Not","Are","With","From","This","That","Have","They","Will","Would","Should","Could","Each","Every","Some","Many","Most","More","Less","Very","Just","Only","Also","Even","Such","Than","Then","When","Where","What","Which","While","After","Before","During","Above","Below","Under","Over","Into","Upon","Within","Without","Through","Across","Around","Behind","Beside","Beyond","Inside","Outside","Toward","Towards"]);
72	  raw.forEach(t => { if (t.length <= 3 || stopWords.has(t)) return; m.set(t, (m.get(t) || 0) + 1); });
73	  return m;
74	}
