76	export function RulebookEditor({ projectId }: { projectId: number }) {
77	  const [state, setState] = useState<RulebookState>(() => load(projectId));
78	  const [expanded, setExpanded] = useState<string | null>(null);
79	  const [tab, setTab] = useState<"outline" | "glossary" | "preview">("outline");
80	  const persist = (next: RulebookState) => { setState(next); save(projectId, next); };
81	
82	  const allText = useMemo(() => state.sections.map(s => s.content).join(" "), [state.sections]);
83	  const detected = useMemo(() => detectTerms(allText), [allText]);
84	
85	  const synced = useMemo(() => {
