89	    existing.forEach(v => merged.push(v));
90	    return merged.sort((a, b) => b.occurrences - a.occurrences);
91	  }, [detected, state.glossary]);
92	
93	  const updateSection = (id: string, u: Partial<RulebookSection>) => persist({ ...state, sections: state.sections.map(s => s.id === id ? { ...s, ...u } : s) });
94	  const moveSection = (id: string, dir: -1 | 1) => { const i = state.sections.findIndex(s => s.id === id); if (i < 0) return; const j = i + dir; if (j < 0 || j >= state.sections.length) return; const arr = [...state.sections]; [arr[i], arr[j]] = [arr[j], arr[i]]; persist({ ...state, sections: arr.map((s, idx) => ({ ...s, order: idx })) }); };
95	  const addSection = () => { const s: RulebookSection = { id: crypto.randomUUID(), type: "custom", title: "New Section", content: "", order: state.sections.length, required: false, tips: [] }; persist({ ...state, sections: [...state.sections, s] }); setExpanded(s.id); };
96	  const removeSection = (id: string) => { persist({ ...state, sections: state.sections.filter(s => s.id !== id).map((s, i) => ({ ...s, order: i })) }); if (expanded === id) setExpanded(null); };
97	
