108	    const defined = synced.filter(g => g.definition.trim());
109	    if (defined.length > 0) { md += `---\n\n## Glossary\n\n`; defined.forEach(g => { md += `**${g.term}** — ${g.definition}  \n`; }); }
110	    return md;
111	  }, [state, synced]);
112	
113	  const sectionsMissing = state.sections.filter(s => s.required && !s.content.trim()).length;
114	  const sectionsTotal = state.sections.filter(s => s.content.trim()).length;
