120	        <p className="text-muted-foreground text-sm mt-1">Structured outline with auto-glossary generation.</p>
121	      </div>
122	
123	      <div className="flex items-center gap-3 flex-wrap">
124	        <Badge variant="outline">{sectionsTotal}/{state.sections.length} sections filled</Badge>
125	        {sectionsMissing > 0 && <Badge className="bg-amber-500/20 text-amber-400 border-amber-500/30 gap-1"><Lightbulb className="h-3 w-3"/> {sectionsMissing} required empty</Badge>}
126	        <Badge variant="outline">{synced.filter(g => g.definition.trim()).length} glossary terms</Badge>
127	      </div>
128	
129	      <div className="flex gap-2 border-b border-border pb-1">
130	        {(["outline","glossary","preview"] as const).map(t => <button key={t} onClick={()=>setTab(t)} className={`px-3 py-2 text-sm font-medium capitalize rounded-t-lg ${tab===t?"bg-sidebar-primary text-sidebar-primary-foreground":"text-muted-foreground hover:text-foreground"}`}>{t}</button>)}
131	      </div>
132	
133	      {tab === "outline" && (
134	        <div className="space-y-4">
135	          <Card>
136	            <CardContent className="space-y-3 pt-6">
137	              <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
138	                <div className="space-y-1"><Label>Title</Label><Input value={state.title} onChange={e=>persist({...state,title:e.target.value})} placeholder="Rulebook title"/></div>
139	                <div className="space-y-1"><Label>Version</Label><Input value={state.version} onChange={e=>persist({...state,version:e.target.value})} placeholder="1.0"/></div>
140	                <div className="space-y-1"><Label>Designer Notes</Label><Input value={state.notes} onChange={e=>persist({...state,notes:e.target.value})} placeholder="Internal notes"/></div>
141	              </div>
142	            </CardContent>
143	          </Card>
144	
145	          <div className="flex items-center justify-between">
146	            <h3 className="font-semibold">Sections</h3>
147	            <Button size="sm" variant="outline" onClick={addSection} className="gap-1"><Plus className="h-4 w-4"/> Add Section</Button>
148	          </div>
149	
150	          <div className="space-y-3">
151	            {state.sections.map((s, idx) => {
152	              const isEx = expanded === s.id;
153	              const meta = META[s.type] || META.custom;
154	              return (
155	                <Card key={s.id} className={`border-l-4 ${meta.color.split(" ")[2]||"border-muted"} ${isEx?"border-primary/50":""}`}>
156	                  <CardHeader className="pb-2 cursor-pointer" onClick={()=>setExpanded(isEx?null:s.id)}>
157	                    <div className="flex items-center justify-between">
158	                      <div className="flex items-center gap-3">
159	                        {isEx?<ChevronDown className="h-4 w-4 text-muted-foreground"/>:<ChevronRight className="h-4 w-4 text-muted-foreground"/>}
160	                        <div className="flex items-center gap-2">
161	                          <Badge className={`${meta.color} text-xs`}>{s.type.replace("-"," ")}</Badge>
162	                          <CardTitle className="text-base">{s.title}</CardTitle>
163	                          {s.required&&<Badge variant="outline" className="text-xs">Required</Badge>}
164	                        </div>
165	                      </div>
166	                      <div className="flex items-center gap-1">
167	                        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={e=>{e.stopPropagation();moveSection(s.id,-1);}} disabled={idx===0}><ArrowUp className="h-3 w-3"/></Button>
168	                        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={e=>{e.stopPropagation();moveSection(s.id,1);}} disabled={idx===state.sections.length-1}><ArrowDown className="h-3 w-3"/></Button>
169	                        <Button variant="ghost" size="icon" className="h-7 w-7 text-destructive" onClick={e=>{e.stopPropagation();removeSection(s.id);}}><Trash2 className="h-3.5 w-3.5"/></Button>
170	                      </div>
171	                    </div>
172	                  </CardHeader>
173	                  {isEx && (
174	                    <CardContent className="space-y-4 pt-0">
175	                      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
176	                        <div className="space-y-1"><Label>Title</Label><Input value={s.title} onChange={e=>updateSection(s.id,{title:e.target.value})} className="h-8 text-sm"/></div>
177	                        <div className="space-y-1"><Label>Type</Label><Select value={s.type} onValueChange={v=>updateSection(s.id,{type:v as any})}><SelectTrigger className="h-8 text-sm"><SelectValue/></SelectTrigger><SelectContent>{["setup","objective","turn-order","actions","scoring","faq","custom"].map(t=><SelectItem key={t} value={t}>{t.replace("-"," ")}</SelectItem>)}</SelectContent></Select></div>
178	                        <div className="flex items-end pb-1 gap-2"><Switch checked={s.required} onCheckedChange={c=>updateSection(s.id,{required:c})}/><span className="text-sm">Required</span></div>
179	                      </div>
180	                      <div className="space-y-1"><Label>Content</Label><Textarea rows={6} value={s.content} onChange={e=>updateSection(s.id,{content:e.target.value})} placeholder={`Write the ${s.title.toLowerCase()} section...`} className="text-sm font-mono"/></div>
181	                      {s.tips.length > 0 && <div className="flex flex-wrap gap-2">{s.tips.map((tip,i)=><Badge key={i} variant="outline" className="gap-1 text-xs"><Lightbulb className="h-3 w-3 text-amber-400"/>{tip}</Badge>)}</div>}
182	                    </CardContent>
183	                  )}
184	                </Card>
185	              );
186	            })}
187	          </div>
188	        </div>
189	      )}
190	
191	      {tab === "glossary" && (
192	        <div className="space-y-4">
193	          <Card>
194	            <CardHeader><CardTitle className="text-base flex items-center gap-2"><Languages className="h-4 w-4 text-primary"/> Auto-Glossary</CardTitle><CardDescription>Terms detected from section content. Add definitions to include in the rulebook.</CardDescription></CardHeader>
195	            <CardContent className="space-y-3">
196	              {synced.length === 0 && <div className="text-sm text-muted-foreground">Write content in sections to detect glossary terms automatically.</div>}
197	              {synced.map(g => (
198	                <div key={g.term} className={`flex items-start gap-3 p-3 rounded-lg border ${g.definition.trim()?"bg-emerald-500/5 border-emerald-500/20":"bg-muted/30 border-transparent"}`}>
199	                  <div className="min-w-0 flex-1">
