145	// ── Gamma dialog ──────────────────────────────────────────────────────────────
146	
147	function GammaDialog({
148	  open, onClose, title, prompt, onSend,
149	}: {
150	  open: boolean;
151	  onClose: () => void;
152	  title: string;
153	  prompt: string;
154	  onSend: (prompt: string) => void;
155	}) {
156	  const [edited, setEdited] = useState(prompt);
157	  useEffect(() => { if (open) setEdited(prompt); }, [open, prompt]);
158	
159	  return (
160	    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
161	      <DialogContent className="max-w-2xl bg-card border-border">
162	        <DialogHeader>
163	          <DialogTitle className="flex items-center gap-2">
164	            <FileText className="h-4 w-4 text-primary" /> Generate with Gamma
165	          </DialogTitle>
166	          <DialogDescription className="text-sm text-muted-foreground">
167	            {title} — review and edit the prompt, then send it to the AI chat.
168	          </DialogDescription>
169	        </DialogHeader>
170	        <Textarea
171	          value={edited}
172	          onChange={(e) => setEdited(e.target.value)}
